217→func assertTranscriptSemantics(t *testing.T, path string, want transcriptExpectations) {
218→	t.Helper()
219→	agent := New()
220→	position, err := agent.GetTranscriptPosition(path)
221→	if err != nil {
222→		t.Fatal(err)
223→	}
224→	if position != want.position {
225→		t.Errorf("position = %d, want %d", position, want.position)
226→	}
227→	files, current, err := agent.ExtractModifiedFiles(path, 0)
228→	if err != nil {
229→		t.Fatal(err)
230→	}
231→	if !slices.Equal(files, want.files) || current != want.position {
232→		t.Errorf("files/current = %v/%d, want %v/%d", files, current, want.files, want.position)
233→	}
234→	prompts, err := agent.ExtractPrompts(path, 0)
235→	if err != nil {
236→		t.Fatal(err)
237→	}
238→	if !slices.Equal(prompts, want.prompts) {
239→		t.Errorf("prompts = %v, want %v", prompts, want.prompts)
240→	}
241→	summary, ok, err := agent.ExtractSummary(path)
242→	if err != nil {
243→		t.Fatal(err)
244→	}
245→	if !ok || summary != want.summary {
246→		t.Errorf("summary = %q/%v, want %q/true", summary, ok, want.summary)
247→	}
248→	data := readFixture(t, path)
249→	usage, err := agent.CalculateTokens(data, 0)
250→	if err != nil {
251→		t.Fatal(err)
252→	}
253→	if usage != want.usage {
254→		t.Errorf("usage = %+v, want %+v", usage, want.usage)
255→	}
256→	if want.model != "" && executionModel(data) != want.model {
257→		t.Errorf("model = %q, want %q", executionModel(data), want.model)
258→	}
259→	compact, err := agent.CompactTranscript(path)
260→	if err != nil {
261→		t.Fatal(err)
262→	}
263→	decoded, err := base64.StdEncoding.DecodeString(compact.Transcript)
264→	if err != nil {
265→		t.Fatal(err)
266→	}
267→	for _, line := range bytes.Split(bytes.TrimSpace(decoded), []byte("\n")) {
268→		if len(line) == 0 {
269→			continue
270→		}
271→		var record map[string]any
272→		if err := json.Unmarshal(line, &record); err != nil {
273→			t.Fatalf("compact transcript contains invalid JSONL %q: %v", line, err)
274→		}
275→	}
276→	for _, expected := range want.compactContains {
277→		if !bytes.Contains(decoded, []byte(expected)) {
278→			t.Errorf("compact transcript does not contain %q:\n%s", expected, decoded)
279→		}
280→	}
281→}
