}"},{"rank":3,"score":10.0881,"file_path":"proofgate/warehouse/client.go","start_line":162,"end_line":194,"focus_line":187,"snippet_start_line":162,"snippet_end_line":194,"symbol_start_line":162,"symbol_end_line":194,"language":"Go","kind":"method","symbol_id":"gh/Subramanyarao11/external-agents:Go:proofgate/warehouse/client.go:method:Client.execute","symbol_name":"execute","qualified_name":"Client.execute","signature":"func (client *Client) execute(ctx context.Context, method, path string, body any) (statementResponse, error)","signals":["path","body","graph:callers","complete-symbol"],"snippet":"func (client *Client) execute(ctx context.Context, method, path string, body any) (statementResponse, error) {
