}"},{"rank":4,"score":10.0183,"file_path":"proofgate/cmd/proofgate/main.go","start_line":39,"end_line":81,"focus_line":67,"snippet_start_line":39,"snippet_end_line":81,"symbol_start_line":39,"symbol_end_line":81,"language":"Go","kind":"function","symbol_id":"gh/Subramanyarao11/external-agents:Go:proofgate/cmd/proofgate/main.go:function:export","symbol_name":"export","qualified_name":"export","signature":"func export(args []string, stdout io.Writer) error","signals":["body","graph:callers","complete-symbol"],"snippet":"func export(args []string, stdout io.Writer) error {
